const { readFileSync, writeFileSync } = require("node:fs");
const { join } = require("node:path");
const dir = join(__dirname, "../src/services/sites/gate-runner");
const src = readFileSync(join(dir, "runner.cjs"), "utf-8");
const out =
  "// GENERATED by apps/backend/scripts/generate-gate-runner-source.cjs from runner.cjs. Do not edit.\n" +
  "export const GATE_RUNNER_SOURCE: string = " + JSON.stringify(src) + ";\n";
writeFileSync(join(dir, "runner-source.generated.ts"), out);
console.log("wrote runner-source.generated.ts (" + src.length + " chars)");
